// Names and words for Joshua to Esther, with meanings and double meanings. Checked with audit.js.
// Names and words for the historical books: Joshua through Esther. Every new card key starts with ot1_.
// Name meanings follow the verse where the text gives one; where the meaning is uncertain the card says so.
const OT1=(o)=>Object.assign({lang:"Hebrew",books:["1sam"],more:[],resp:"",say:"",heb:"",tr:"",strong:""},o);
Object.assign(TERMS,{
// ================= Joshua =================
ot1_rahab:OT1({name:"Rahab",forms:["Rahab"],resp:"RAY-hab",say:"ray hab",heb:"רָחָב",tr:"Rachav",strong:"H7343",books:["josh"],
 plain:"A woman of Jericho who hid Joshua’s two spies and was spared with her family when the city fell (Joshua 2:1–6; 6:25). The name means “broad” or “wide.”",
 bg:"The “line of scarlet thread” she hung in her window (2:18) uses the Hebrew word tiqvah, which means both “cord” and “hope.” The New Testament honors her faith and lists her in Jesus’ ancestry (Hebrews 11:31; Matthew 1:5)."}),
ot1_achan:OT1({name:"Achan",forms:["Achan"],resp:"AY-kan",say:"ay kan",heb:"עָכָן",tr:"ʿAkhan",strong:"H5912",books:["josh"],
 plain:"An Israelite of Judah who kept silver, gold and a fine garment from Jericho against the ban, and so brought defeat on Israel at Ai (Joshua 7:1, 20–21). Joshua plays on his name with a similar-sounding word: “Why hast thou troubled us? the LORD shall trouble thee this day” (7:25).",
 bg:"First Chronicles calls him Achar, “the troubler of Israel” (1 Chronicles 2:7), and the place of his punishment was called the valley of Achor, “trouble” (Joshua 7:26)."}),
ot1_herem:OT1({name:"accursed thing (herem)",forms:["accursed"],resp:"KHEH-rem",say:"kheh rem",heb:"חֵרֶם",tr:"cherem",strong:"H2764",books:["josh"],
 plain:"The KJV’s “accursed” translates herem, something set apart to the LORD and so not to be used by anyone, usually by being destroyed (Joshua 6:17–18). Anyone who kept part of it came under the same ban (7:11–12).",
 bg:"Achan took from the herem and was himself put under it (7:15, 24–25). The same Semitic root gives the Arabic words haram and harem, “forbidden” and “set apart.”"}),
ot1_gibeon:OT1({name:"Gibeon",forms:["Gibeon","Gibeonites"],resp:"GIB-ee-un",say:"gib ee un",heb:"גִּבְעוֹן",tr:"Givʿon",strong:"H1391",books:["josh","2sam","1kgs","neh"],
 plain:"A large Hivite city whose people tricked Israel into a treaty by pretending to come from far away (Joshua 9:3–15). The name probably comes from givʿah, “hill.”",
 bg:"The sun stood still “upon Gibeon” while Israel fought for the city (Joshua 10:12–13). Solomon later offered sacrifices at “the great high place” there, and the LORD appeared to him in a dream (1 Kings 3:4–5)."}),
ot1_hebron:OT1({name:"Hebron",forms:["Hebron"],resp:"HEE-brun",say:"hee brun",heb:"חֶבְרוֹן",tr:"Chevron",strong:"H2275",books:["josh","judg","1sam","2sam","1kgs"],
 plain:"A hill-country city of Judah where Abraham and Sarah were buried (Genesis 23:19). The name is often explained as “association” or “league,” from a root meaning “to join,” but this is not certain.",
 bg:"Caleb received it as his inheritance (Joshua 14:13–14), and David was anointed king over Judah there and reigned in Hebron seven years and six months before all Israel anointed him (2 Samuel 2:1–4, 11; 5:1–5)."}),
ot1_gilgal:OT1({name:"Gilgal",forms:["Gilgal"],resp:"GIL-gal",say:"gil gal",heb:"גִּלְגָּל",tr:"Gilgal",strong:"H1537",books:["josh","judg","1sam","2sam","2kgs"],
 plain:"Israel’s first camp west of the Jordan, near Jericho, where they set up twelve stones from the riverbed (Joshua 4:19–20). The LORD names it there: “This day have I rolled away the reproach of Egypt from off you. Wherefore the name of the place is called Gilgal” (5:9).",
 bg:"Gilgal sounds like galal, “to roll,” and also means “circle” (of stones). It stayed Israel’s base in the conquest (Joshua 9:6; 10:6–7) and was where Saul was confirmed as king and later rejected (1 Samuel 11:14–15; 13:7–14)."}),
ot1_gilgal_other:OT1({name:"Gilgal (another place)",forms:[],resp:"GIL-gal",say:"gil gal",heb:"גִּלְגָּל",tr:"Gilgal",strong:"H1537",books:["josh","2kgs"],
 plain:"“Gilgal” (“circle”) was the name of more than one place, and here the writer seems to mean a different one from the camp near Jericho. Joshua 15:7 is a landmark on Judah’s border, called Geliloth in 18:17; Joshua 12:23 names a “king of the nations of Gilgal”; and in 2 Kings 2:1–2 Elijah and Elisha go “down” from Gilgal to Beth-el, so it must lie higher in the hills.",
 bg:"Which Gilgal is meant in each verse is a judgment from the text and geography, and scholars differ on some of them."}),
ot1_shiloh:OT1({name:"Shiloh",forms:["Shiloh"],resp:"SHY-lo",say:"shy lo",heb:"שִׁלֹה",tr:"Shiloh",strong:"H7887",books:["josh","judg","1sam","1kgs"],
 plain:"A town in the hills of Ephraim where Israel set up the tabernacle and divided the rest of the land (Joshua 18:1, 8–10). The name probably means “tranquil place” or “place of rest,” but the meaning is uncertain.",
 bg:"Eli and the ark were at Shiloh when Samuel was born and called (1 Samuel 1:3; 3:21). Centuries later Jeremiah used its ruins as a warning: “go ye now unto my place which was in Shiloh” (Jeremiah 7:12)."}),
ot1_amorites:OT1({name:"Amorites",forms:["Amorites","Amorite"],resp:"AM-uh-rites",say:"am uh rites",heb:"אֱמֹרִי",tr:"ʾEmori",strong:"H567",books:["josh","judg","1sam","2sam","1kgs","2kgs","ezra","neh"],
 plain:"One of the peoples living in Canaan, often used in the Bible as a general word for all the pre-Israelite inhabitants (Joshua 24:15, 18). Mesopotamian texts call the western peoples Amurru, “the west,” and some think the Hebrew name means the same.",
 bg:"Israel defeated the two Amorite kings east of the Jordan, Sihon and Og (Joshua 2:10; 24:8)."}),
ot1_hittites:OT1({name:"Hittites",forms:["Hittites","Hittite"],resp:"HIT-ites",say:"hit ites",heb:"חִתִּי",tr:"Chitti",strong:"H2850",books:["josh","judg","1sam","2sam","1kgs","2kgs","ezra","neh"],
 plain:"A people of Canaan descended from Heth, a son of Canaan (Genesis 10:15). The best-known Hittite in the Bible is Uriah, one of David’s thirty mighty men (2 Samuel 11:3; 23:39); the meaning of Heth is uncertain.",
 bg:"A great Hittite empire ruled what is now Turkey from the city Hattusa. Scholars debate how it relates to the Hittites of the Bible, who appear as smaller groups in Canaan."}),
// ================= Judges =================
ot1_othniel:OT1({name:"Othniel",forms:["Othniel"],resp:"OTH-nee-el",say:"oth nee el",heb:"עָתְנִיאֵל",tr:"ʿOtniʾel",strong:"H6274",books:["josh","judg"],
 plain:"Caleb’s younger kinsman (the KJV says “younger brother”), who won Caleb’s daughter Achsah by capturing Kirjath-sepher (Joshua 15:16–17; Judges 1:13) and became Israel’s first judge (3:9–11). The name is sometimes explained as “lion of God,” but the meaning is uncertain.",
 bg:"“The Spirit of the LORD came upon him, and he judged Israel” (Judges 3:10)."}),
ot1_cushan:OT1({name:"Chushan-rishathaim",forms:["Chushan-rishathaim"],resp:"KOO-shan rish-uh-THAY-im",say:"koo shan rish uh thay im",heb:"כּוּשַׁן רִשְׁעָתַיִם",tr:"Kushan Rishʿatayim",strong:"H3573",books:["judg"],
 plain:"The king of Mesopotamia who oppressed Israel for eight years until Othniel defeated him (Judges 3:8–10). The name means “Cushan of double wickedness,” and many scholars think the writer gave him this mocking name.",
 bg:"His real name is not preserved; “Chushan” may be a place or people’s name."}),
ot1_ehud:OT1({name:"Ehud",forms:["Ehud"],resp:"EE-hud",say:"ee hud",heb:"אֵהוּד",tr:"ʾEhud",strong:"H164",books:["judg"],
 plain:"A Benjamite judge who killed Eglon, king of Moab, with a short double-edged sword and freed Israel (Judges 3:15–30). The meaning of the name is uncertain.",
 bg:"He is “a man lefthanded” (3:15), literally “bound in his right hand,” a phrase also used of the Benjamite slingers in 20:16. It is a play on Benjamin, “son of the right hand.”"}),
ot1_eglon:OT1({name:"Eglon",forms:["Eglon"],resp:"EG-lon",say:"egg lon",heb:"עֶגְלוֹן",tr:"ʿEglon",strong:"H5700",books:["judg"],
 plain:"The king of Moab who took Jericho and made Israel pay tribute for eighteen years; he “was a very fat man” and was killed by Ehud (Judges 3:12–25). The name comes from ʿegel, “calf.”",
 bg:"Many readers see the name as part of the joke: a fattened calf led to slaughter."}),
ot1_deborah:OT1({name:"Deborah",forms:["Deborah"],resp:"DEB-or-uh",say:"deb or uh",heb:"דְּבוֹרָה",tr:"Devorah",strong:"H1683",books:["judg"],
 plain:"A prophetess who judged Israel from under a palm tree between Ramah and Beth-el and sent for Barak to fight Sisera (Judges 4:4–7). The name means “bee.”",
 bg:"She is the only woman among the judges, and her victory song in Judges 5 is often counted among the oldest poems in the Bible."}),
ot1_barak:OT1({name:"Barak",forms:["Barak"],resp:"BAIR-ak",say:"bair ak",heb:"בָּרָק",tr:"Baraq",strong:"H1301",books:["judg"],
 plain:"The man from Kedesh-naphtali whom Deborah called to lead ten thousand men against Sisera’s army (Judges 4:6–16). The name means “lightning.”",
 bg:"He would not go unless Deborah went with him, so she said the honor of Sisera’s death would go to a woman (4:8–9)."}),
ot1_jael:OT1({name:"Jael",forms:["Jael"],resp:"JAY-el",say:"jay el",heb:"יָעֵל",tr:"Yaʿel",strong:"H3278",books:["judg"],
 plain:"The wife of Heber the Kenite, who killed the sleeping Sisera with a tent peg (Judges 4:17–22). The name means “mountain goat” or “ibex.”",
 bg:"Deborah’s song says, “Blessed above women shall Jael … be, blessed shall she be above women in the tent” (5:24)."}),
ot1_sisera:OT1({name:"Sisera",forms:["Sisera"],resp:"SIS-er-uh",say:"sis er uh",heb:"סִיסְרָא",tr:"Sisra",strong:"H5516",books:["judg","1sam"],
 plain:"The commander of King Jabin’s army, with nine hundred chariots of iron, defeated at the river Kishon and killed by Jael (Judges 4:2–3, 15–22). The name does not seem to be Hebrew, and its meaning is uncertain.",
 bg:"Deborah sang, “They fought from heaven; the stars in their courses fought against Sisera” (5:20)."}),
ot1_gideon:OT1({name:"Gideon / Jerubbaal",forms:["Gideon","Jerubbaal"],resp:"GID-ee-un",say:"gid ee un",heb:"גִּדְעוֹן",tr:"Gidʿon",strong:"H1439",books:["judg","1sam"],
 plain:"A farmer’s son from Manasseh whom the angel of the LORD greeted, while he threshed wheat in hiding, as “thou mighty man of valour” (Judges 6:11–12). His name seems to come from a word meaning “to cut down,” fitting how he cut down his father’s Baal altar and its grove (6:25–27).",
 bg:"His second name, Jerubbaal, means “let Baal plead,” given when his father said, “Let Baal plead against him, because he hath thrown down his altar” (6:32). With only three hundred men he routed Midian (7:7)."}),
ot1_orebzeeb:OT1({name:"Oreb and Zeeb",forms:["Oreb","Zeeb"],resp:"OR-eb, ZEE-eb",say:"or eb, zee eb",heb:"עֹרֵב וּזְאֵב",tr:"ʿOrev, Zeʾev",strong:"",books:["judg"],
 plain:"Two Midianite princes caught and killed by the men of Ephraim (Judges 7:25). Oreb means “raven” and Zeeb means “wolf,” and the places were named for them: “the rock Oreb” and “the winepress of Zeeb.”",
 bg:"Isaiah later recalls “the slaughter of Midian at the rock of Oreb” (Isaiah 10:26)."}),
ot1_abimelech:OT1({name:"Abimelech",forms:["Abimelech"],resp:"uh-BIM-eh-lek",say:"uh bim eh leck",heb:"אֲבִימֶלֶךְ",tr:"ʾAvimelekh",strong:"H40",books:["judg","2sam"],
 plain:"Gideon’s son by a concubine at Shechem, who killed seventy of his brothers and had himself made king (Judges 9:1–6). His name means “my father is king,” though Gideon had said, “the LORD shall rule over you” (8:23).",
 bg:"Only the youngest brother, Jotham, escaped, and told the fable of the trees choosing a bramble for king (9:7–15). Abimelech died when a woman dropped a millstone on his head (9:53; 2 Samuel 11:21)."}),
ot1_jephthah:OT1({name:"Jephthah",forms:["Jephthah"],resp:"JEF-thuh",say:"jef thuh",heb:"יִפְתָּח",tr:"Yiftach",strong:"H3316",books:["judg","1sam"],
 plain:"A mighty man of Gilead, driven out by his half-brothers and later called back to lead Israel against Ammon (Judges 11:1–11). The name probably means “he opens,” but the meaning is not certain.",
 bg:"He made a vow before the battle (11:30–31) and “did with her according to his vow” (11:39); readers have long debated whether his daughter was sacrificed or dedicated to the LORD’s service. Hebrews 11:32 lists him among the faithful."}),
ot1_shibboleth:OT1({name:"Shibboleth",forms:["Shibboleth","Sibboleth"],resp:"SHIB-uh-leth",say:"shib uh leth",heb:"שִׁבֹּלֶת",tr:"shibbolet",strong:"H7641",books:["judg"],
 plain:"The password the men of Gilead used at the Jordan to catch fleeing Ephraimites, who could not say the “sh” sound and said “Sibboleth” instead (Judges 12:5–6). The Hebrew word means “ear of grain” or “stream.”",
 bg:"Forty-two thousand Ephraimites died there (12:6). In English a “shibboleth” is any test word or custom that shows who belongs to a group."}),
ot1_samson:OT1({name:"Samson",forms:["Samson"],resp:"SAM-sun",say:"sam sun",heb:"שִׁמְשׁוֹן",tr:"Shimshon",strong:"H8123",books:["judg"],
 plain:"A judge from the tribe of Dan, a Nazarite from birth, famous for his strength and for his fight with the Philistines (Judges 13:24–25; 15:14–16; 16:30–31). His name seems to come from shemesh, “sun,” so “little sun” or “sun-like.”",
 bg:"He was born after an angel promised a childless woman a son (13:2–5), and his home country lay near Beth-shemesh, “house of the sun.” Hebrews 11:32 lists him among the faithful."}),
ot1_delilah:OT1({name:"Delilah",forms:["Delilah"],resp:"dih-LY-luh",say:"dih lye luh",heb:"דְּלִילָה",tr:"Delilah",strong:"H1807",books:["judg"],
 plain:"The woman in the valley of Sorek whom Samson loved, and whom the Philistine lords paid to learn the secret of his strength (Judges 16:4–6, 18). The meaning of her name is uncertain; some link it to laylah, “night,” and others to a root meaning “weak” or “hanging.”",
 bg:"The text does not say whether she was an Israelite or a Philistine."}),
ot1_manoah:OT1({name:"Manoah",forms:["Manoah"],resp:"muh-NO-uh",say:"muh no uh",heb:"מָנוֹחַ",tr:"Manoach",strong:"H4495",books:["judg"],
 plain:"Samson’s father, of the tribe of Dan, who prayed to see the angel again after his unnamed wife had met him (Judges 13:2–23). The name probably means “rest.”",
 bg:"His wife reasoned better than he did when he feared they would die: “If the LORD were pleased to kill us, he would not have received a burnt offering” (13:23)."}),
ot1_nazarite:OT1({name:"Nazarite",forms:["Nazarite"],resp:"NAZ-uh-rite",say:"naz uh rite",heb:"נָזִיר",tr:"nazir",strong:"H5139",books:["judg"],
 plain:"Someone who took a special vow to be set apart to the LORD, avoiding wine and grapes, cutting the hair, and touching the dead (Numbers 6:1–8). The Hebrew nazir comes from a root meaning “to dedicate” or “to separate.”",
 bg:"The vow was usually for a set time, but Samson’s was for life (Judges 13:5, 7; 16:17). A Nazarite is not a Nazarene, a man from Nazareth."}),
ot1_lehi:OT1({name:"Lehi / Ramath-lehi",forms:["Ramath-lehi","Lehi"],resp:"LEE-hy",say:"lee high",heb:"לְחִי",tr:"Lechi",strong:"H3896",books:["judg"],
 plain:"The place where Samson struck down a thousand Philistines with the jawbone of a donkey (Judges 15:9–17). Lehi means “jaw” or “jawbone,” and Samson named the spot Ramath-lehi, “height of the jawbone” (15:17).",
 bg:"The Book of Mormon prophet Lehi, father of Nephi, has the same name (1 Nephi 1:4), though the Book of Mormon does not explain it."}),
ot1_baalberith:OT1({name:"Baal-berith",forms:["Baal-berith"],resp:"BAH-al be-RITH",say:"bah al be rith",heb:"בַּעַל בְּרִית",tr:"Baʿal Berit",strong:"",books:["judg"],
 plain:"A god worshipped at Shechem. After Gideon died, Israel “made Baal-berith their god” (Judges 8:33), and Abimelech hired his followers with silver from the god’s house (9:4). The name means “lord of the covenant.”",
 bg:"The irony is that Israel, bound in covenant to the LORD, chose a “lord of the covenant” of their own. The temple is also called the house of the god Berith (9:46)."}),
// ================= Ruth =================
ot1_naomi:OT1({name:"Naomi / Mara",forms:["Naomi","Mara"],resp:"nay-OH-mee",say:"nay oh mee",heb:"נָעֳמִי",tr:"Noʿomi",strong:"H5281",books:["ruth"],
 plain:"Elimelech’s wife, who went to Moab in a famine, lost her husband and both sons, and came back to Beth-lehem with Ruth (Ruth 1:1–22). Her name means “my pleasant one.”",
 bg:"She asked to be called Mara, “bitter”: “call me Mara: for the Almighty hath dealt very bitterly with me” (1:20). At the end the women say, “There is a son born to Naomi” (4:17)."}),
ot1_elimelech:OT1({name:"Elimelech",forms:["Elimelech"],resp:"ih-LIM-eh-lek",say:"ih lim eh leck",heb:"אֱלִימֶלֶךְ",tr:"ʾElimelekh",strong:"H458",books:["ruth"],
 plain:"Naomi’s husband, from Beth-lehem-judah, who took his family to Moab in a famine and died there (Ruth 1:1–3). The name means “my God is king.”",
 bg:"The story is set “in the days when the judges ruled” (1:1), when “there was no king in Israel” (Judges 21:25)."}),
ot1_mahlon:OT1({name:"Mahlon and Chilion",forms:["Mahlon","Chilion"],resp:"MAH-lon, KIL-ee-on",say:"mah lon, kil ee on",heb:"מַחְלוֹן כִּלְיוֹן",tr:"Machlon, Kilyon",strong:"H4248 / H3630",books:["ruth"],
 plain:"Naomi’s two sons, who married Moabite women and then died in Moab (Ruth 1:2–5). The names are often explained as “sickly” and “failing” (or “wasting”), which seem to foreshadow their early deaths, but the meanings are uncertain.",
 bg:"Mahlon was Ruth’s husband, and Boaz bought the family land “to raise up the name of the dead upon his inheritance” (4:10)."}),
ot1_ruth:OT1({name:"Ruth",forms:["Ruth"],resp:"ROOTH",say:"rooth",heb:"רוּת",tr:"Rut",strong:"H7327",books:["ruth"],
 plain:"A Moabite widow who stayed with her mother-in-law Naomi and later married Boaz (Ruth 1:16; 4:13). The name may mean “friend” or “companion,” but the meaning is uncertain.",
 bg:"She said, “thy people shall be my people, and thy God my God” (1:16). She became David’s great-grandmother (4:17–22) and is named in Jesus’ ancestry (Matthew 1:5)."}),
ot1_boaz:OT1({name:"Boaz",forms:["Boaz"],resp:"BO-az",say:"bo az",heb:"בֹּעַז",tr:"Boʿaz",strong:"H1162",books:["ruth"],
 plain:"A wealthy relative of Elimelech in Beth-lehem who let Ruth glean in his field and then, as a kinsman, married her (Ruth 2:1–3; 4:13). The name is often explained as “in him is strength,” but this is uncertain.",
 bg:"His son Obed was David’s grandfather (4:21–22), and Matthew lists Boaz in Jesus’ ancestry (Matthew 1:5). A bronze pillar of Solomon’s temple also bore this name (1 Kings 7:21)."}),
ot1_goel:OT1({name:"kinsman, redeem (go’el)",forms:["kinsman","kinsmen","redeem","redeeming"],resp:"go-ALE",say:"go ale",heb:"גֹּאֵל",tr:"goʾel",strong:"H1350",books:["ruth"],
 plain:"In Ruth, “kinsman” and “redeem” come from the same Hebrew family of words, goʾel and gaʾal: the nearest relative who had the duty to buy back a family’s land and protect its widow (Ruth 3:12–13; 4:4–6). Boaz was a near kinsman, though not the nearest (3:12).",
 bg:"The same word is used of God: “thy redeemer, the Holy One of Israel” (Isaiah 41:14)."}),
ot1_obed:OT1({name:"Obed",forms:["Obed"],resp:"O-bed",say:"o bed",heb:"עוֹבֵד",tr:"ʿOved",strong:"H5744",books:["ruth"],
 plain:"The son of Ruth and Boaz and grandfather of David (Ruth 4:13–17, 21–22). The name means “servant” or “worshipper,” from the root “to serve.”",
 bg:"Unusually, the neighbor women gave him his name (4:17). He is in the family tree of Jesus (Matthew 1:5)."}),
ot1_jesse:OT1({name:"Jesse",forms:["Jesse"],resp:"JESS-ee",say:"jess ee",heb:"יִשַׁי",tr:"Yishai",strong:"H3448",books:["ruth","1sam","2sam","1kgs"],
 plain:"A man of Beth-lehem, grandson of Boaz and Ruth, with eight sons, the youngest being David (Ruth 4:22; 1 Samuel 16:10–11; 17:12). The meaning of the name is uncertain.",
 bg:"Isaiah promised “a rod out of the stem of Jesse” (Isaiah 11:1), and a revelation to Joseph Smith says “the Stem of Jesse” is Christ (D&C 113:1–2)."}),
ot1_bethlehem:OT1({name:"Beth-lehem",forms:["Beth-lehem-judah","Beth-lehem","Beth-lehemite"],resp:"BETH-leh-hem",say:"beth leh hem",heb:"בֵּית לֶחֶם",tr:"Beit Lechem",strong:"H1035",books:["judg","ruth","1sam","2sam","ezra","neh"],
 plain:"A town in the hills of Judah about six miles south of Jerusalem. The name means “house of bread,” and Ruth plays on it: Naomi returned when she heard “the LORD had visited his people in giving them bread” (Ruth 1:1, 6).",
 bg:"It was the hometown of Jesse and David (1 Samuel 17:12). Micah foretold a ruler from Beth-lehem (Micah 5:2), fulfilled in Jesus (Matthew 2:1–6). There was also a Beth-lehem in Zebulun (Joshua 19:15), and Ibzan of Beth-lehem (Judges 12:8–10) may be from either."}),
// ================= 1 Samuel =================
ot1_hannah:OT1({name:"Hannah",forms:["Hannah"],resp:"HAN-uh",say:"han uh",heb:"חַנָּה",tr:"Channah",strong:"H2584",books:["1sam"],
 plain:"Elkanah’s childless wife, who prayed at Shiloh so deeply that Eli thought she was drunk, and vowed to give a son to the LORD (1 Samuel 1:10–15). The name means “favor” or “grace.”",
 bg:"Her son Samuel was the answer (1:20, 27–28), and her song of praise (2:1–10) is echoed in Mary’s in Luke 1:46–55."}),
ot1_eli:OT1({name:"Eli",forms:["Eli"],resp:"EE-lye",say:"ee lye",heb:"עֵלִי",tr:"ʿEli",strong:"H5941",books:["1sam","1kgs"],
 plain:"The priest at Shiloh who raised the boy Samuel but did not stop his sons from abusing their office (1 Samuel 2:22–25; 3:13). The name probably means “high” or “ascended,” but this is uncertain.",
 bg:"He died at ninety-eight on hearing that the ark was taken (4:15–18). Solomon later removed Abiathar, a descendant of Eli, from the priesthood, fulfilling the word spoken at Shiloh (1 Kings 2:27)."}),
ot1_hophni:OT1({name:"Hophni and Phinehas",forms:["Hophni","Phinehas"],resp:"HOF-nye, FIN-ee-us",say:"hof nye, fin ee us",heb:"חָפְנִי פִּינְחָס",tr:"Chofni, Pinchas",strong:"H2652 / H6372",books:["1sam"],
 plain:"The two sons of Eli, priests at Shiloh, who “were sons of Belial; they knew not the LORD” (1 Samuel 2:12) and took the best of the sacrifices by force (2:13–16). Both died on the day the Philistines took the ark (4:11). Both names are thought to be Egyptian, Hophni perhaps “tadpole” and Phinehas “the Nubian.”",
 bg:"Their deaths in one day were the sign given to Eli (2:34; 4:11). This Phinehas is not Aaron’s grandson of the same name."}),
ot1_ichabod:OT1({name:"I-chabod",forms:["I-chabod"],resp:"EYE-kuh-bod",say:"eye kuh bod",heb:"אִי־כָבוֹד",tr:"Ikhavod",strong:"H350",books:["1sam"],
 plain:"The son of Phinehas, born as his mother died when news came that the ark was captured: “she named the child I-chabod, saying, The glory is departed from Israel” (1 Samuel 4:21). The name means “no glory” or “where is the glory?”",
 bg:"The text ties the name to the ark: “The glory is departed from Israel: for the ark of God is taken” (4:22). His brother Ahiah appears in 14:3."}),
ot1_ebenezer:OT1({name:"Eben-ezer",forms:["Eben-ezer"],resp:"EB-en-EE-zer",say:"eb en ee zer",heb:"אֶבֶן הָעֵזֶר",tr:"Even ha-ʿEzer",strong:"H72",books:["1sam"],
 plain:"A stone Samuel set up after Israel beat the Philistines, naming it: “Hitherto hath the LORD helped us” (1 Samuel 7:12). The name means “stone of help.”",
 bg:"The name also appears earlier, where Israel lost the ark near Eben-ezer (4:1; 5:1), so it may be the same place named in hindsight or a different spot. The hymn “Come, Thou Fount of Every Blessing” borrows the name for a marker of the Lord’s help."}),
ot1_samuel:OT1({name:"Samuel",forms:["Samuel"],resp:"SAM-yoo-el",say:"sam yoo el",heb:"שְׁמוּאֵל",tr:"Shemuʾel",strong:"H8050",books:["1sam"],
 plain:"The last judge of Israel, a prophet and priest who anointed Saul and then David (1 Samuel 10:1; 16:13). The Hebrew looks like “name of God” or “heard of God,” but Hannah explains it with a pun on the word for “ask”: “Because I have asked him of the LORD” (1:20).",
 bg:"The root “ask” (shaʾal) is also the root of Saul’s name, and Hannah says Samuel is “lent” (shaʾul) to the LORD (1:28). He is a different man from Samuel the Lamanite (Helaman 13–16)."}),
ot1_saul:OT1({name:"Saul",forms:["Saul"],resp:"SAWL",say:"sawl",heb:"שָׁאוּל",tr:"Shaʾul",strong:"H7586",books:["1sam","2sam"],
 plain:"The first king of Israel, a tall Benjamite chosen by lot and anointed by Samuel (1 Samuel 9:2; 10:1, 21–24). His name means “asked for,” from shaʾal, “to ask,” a word the story keeps repeating: Israel “asked of him a king” (8:10).",
 bg:"The same word gives “lent” in 1:28, where Samuel is “lent” (shaʾul) to the LORD. Saul lost the kingdom for disobedience (13:13–14; 15:22–23) and died on Mount Gilboa (31:1–6)."}),
ot1_jonathan:OT1({name:"Jonathan",forms:["Jonathan"],resp:"JON-uh-thun",say:"jon uh thun",heb:"יְהוֹנָתָן",tr:"Yehonatan",strong:"H3083",books:["1sam","2sam","1kgs"],
 plain:"Saul’s son and David’s closest friend, who “loved him as his own soul” (1 Samuel 18:1, 3) and gave David his robe and weapons. The name means “the LORD has given.”",
 bg:"He was killed with Saul on Gilboa (31:2); David mourned, “very pleasant hast thou been unto me: thy love to me was wonderful” (2 Samuel 1:26). David later showed kindness to Jonathan’s son (9:1–7)."}),
ot1_jonathan_abiathar:OT1({name:"Jonathan (son of Abiathar)",forms:[],resp:"JON-uh-thun",say:"jon uh thun",heb:"יוֹנָתָן",tr:"Yonatan",strong:"H3129",books:["2sam","1kgs"],
 plain:"The son of the priest Abiathar, who with Ahimaaz carried secret messages to David during Absalom’s revolt (2 Samuel 15:27, 36; 17:17–21). He later brought news of Solomon’s anointing to Adonijah’s feast (1 Kings 1:42–43).",
 bg:"He is a different man from Saul’s son Jonathan."}),
ot1_david:OT1({name:"David",forms:["David"],resp:"DAY-vid",say:"day vid",heb:"דָּוִד",tr:"David",strong:"H1732",books:["ruth","1sam","2sam","1kgs","2kgs","ezra","neh"],
 plain:"Israel’s greatest king, youngest son of Jesse, a shepherd, musician and warrior anointed by Samuel (1 Samuel 16:11–13), who took Jerusalem and received the promise that his house would last forever (2 Samuel 7:16). The name is usually explained as “beloved” (from dod), though some scholars suggest “chieftain,” and it is debated.",
 bg:"His sin with Bathsheba and against Uriah cost him dearly; a revelation says “he hath fallen from his exaltation” (D&C 132:39). Matthew opens the New Testament with “Jesus Christ, the son of David” (Matthew 1:1)."}),
ot1_goliath:OT1({name:"Goliath",forms:["Goliath"],resp:"guh-LY-uth",say:"guh lye uth",heb:"גָּלְיָת",tr:"Golyat",strong:"H1555",books:["1sam","2sam"],
 plain:"The Philistine champion of Gath, “six cubits and a span” tall, who mocked Israel for forty days until David killed him with a sling stone (1 Samuel 17:4, 16, 40–51). The meaning of the name is uncertain, and it may not be Hebrew.",
 bg:"The Dead Sea Scrolls and the Septuagint read “four cubits and a span” (about 6 ft 9 in) instead of six cubits (about 9 ft 9 in). Second Samuel 21:19 credits Elhanan with killing “the brother of” Goliath, words printed in italics in the KJV; 1 Chronicles 20:5 names him Lahmi."}),
ot1_abigail:OT1({name:"Abigail",forms:["Abigail"],resp:"AB-ih-gayl",say:"ab ih gayl",heb:"אֲבִיגַיִל",tr:"ʾAvigayil",strong:"H26",books:["1sam","2sam"],
 plain:"The wise and beautiful wife of the foolish Nabal, who brought David food and talked him out of revenge (1 Samuel 25:3, 18–35), then married him after Nabal died (25:39–42). Her name means “my father is joy.”",
 bg:"David blessed her: “blessed be thy advice, and blessed be thou” (25:33)."}),
ot1_nabal:OT1({name:"Nabal",forms:["Nabal"],resp:"NAY-bal",say:"nay bal",heb:"נָבָל",tr:"Naval",strong:"H5037",books:["1sam","2sam"],
 plain:"A rich sheep-owner of Maon and Carmel who insulted David’s men and refused them food (1 Samuel 25:2–11). His name means “fool,” as his wife says: “as his name is, so is he; Nabal is his name, and folly is with him” (25:25).",
 bg:"About ten days after learning how close he came to disaster, “the LORD smote Nabal, that he died” (25:38). Nabal means a morally foolish person, the word used in Psalm 14:1."}),
ot1_michal:OT1({name:"Michal",forms:["Michal"],resp:"MY-kal",say:"my kal",heb:"מִיכַל",tr:"Mikhal",strong:"H4324",books:["1sam","2sam"],
 plain:"Saul’s younger daughter, who loved David and saved his life by letting him down from a window (1 Samuel 18:20; 19:11–17), but later despised him for dancing before the ark (2 Samuel 6:16, 20–23). The name is probably a short form of “Who is like God?”",
 bg:"Saul gave her to another man, but David demanded her back (1 Samuel 25:44; 2 Samuel 3:13–16). She had no child to the day of her death (6:23)."}),
ot1_abner:OT1({name:"Abner",forms:["Abner"],resp:"AB-ner",say:"ab ner",heb:"אַבְנֵר",tr:"ʾAvner",strong:"H74",books:["1sam","2sam","1kgs"],
 plain:"Saul’s uncle and the commander of his army (1 Samuel 14:50), who made Ish-bosheth king but later turned to David and was killed by Joab (2 Samuel 2:8; 3:12, 27). The name is usually explained as “my father is a lamp”; his father was named Ner, “lamp.”",
 bg:"David mourned him: “Know ye not that there is a prince and a great man fallen this day in Israel?” (3:38)."}),
ot1_agag:OT1({name:"Agag / Agagite",forms:["Agag","Agagite"],resp:"AY-gag",say:"ay gag",heb:"אֲגַג",tr:"ʾAgag",strong:"H90",books:["1sam","esth"],
 plain:"Agag was the king of the Amalekites whom Saul spared and Samuel killed (1 Samuel 15:8–9, 33). Esther calls Haman “the Agagite” (Esther 3:1), tying him to Israel’s old enemy. The name may be a royal title, and its meaning is uncertain.",
 bg:"Mordecai is “the son of Kish, a Benjamite” (Esther 2:5), the same tribe and father’s name as Saul, so the story of Esther can be read as the old conflict with Amalek replayed."}),
// ================= 2 Samuel =================
ot1_joab:OT1({name:"Joab",forms:["Joab"],resp:"JO-ab",say:"jo ab",heb:"יוֹאָב",tr:"Yoʾav",strong:"H3097",books:["1sam","2sam","1kgs"],
 plain:"The son of Zeruiah, David’s sister (1 Chronicles 2:16), and commander of David’s army (2 Samuel 2:13; 8:16). The name means “the LORD is father.”",
 bg:"He killed Abner, Absalom and Amasa (2 Samuel 3:27; 18:14; 20:10), and Solomon had him executed at the altar (1 Kings 2:28–34)."}),
ot1_uriah:OT1({name:"Uriah",forms:["Uriah"],resp:"yoo-RY-uh",say:"yoo rye uh",heb:"אוּרִיָּה",tr:"ʾUriyyah",strong:"H223",books:["2sam","1kgs"],
 plain:"A Hittite warrior among David’s thirty, married to Bathsheba, whom David had placed at the front of the battle so that he would die (2 Samuel 11:3, 14–17; 23:39). The name means “the LORD is my light.”",
 bg:"When David tried to send him home, he refused: “The ark, and Israel, and Judah, abide in tents … shall I then go into mine house?” (11:11)."}),
ot1_bathsheba:OT1({name:"Bath-sheba",forms:["Bath-sheba"],resp:"bath-SHEE-buh",say:"bath shee buh",heb:"בַּת־שֶׁבַע",tr:"Bat-Shevaʿ",strong:"H1339",books:["2sam","1kgs"],
 plain:"Uriah’s wife, whom David took and married after Uriah’s death; their first child died, and their second was Solomon (2 Samuel 11:2–4, 27; 12:15–24). The name is explained as “daughter of an oath,” “daughter of seven,” or “daughter of Sheba,” and the meaning is uncertain.",
 bg:"In 1 Kings 1:11–31 she secures the throne for Solomon. Matthew calls her only “her that had been the wife of Urias” (Matthew 1:6)."}),
ot1_nathan:OT1({name:"Nathan",forms:["Nathan"],resp:"NAY-thun",say:"nay thun",heb:"נָתָן",tr:"Natan",strong:"H5416",books:["2sam","1kgs"],
 plain:"The prophet who brought David God’s promise of a lasting house (2 Samuel 7:2–17), told him the story of the ewe lamb and said, “Thou art the man” (12:1–7), and helped put Solomon on the throne (1 Kings 1:8–45). The name means “he gave,” a short form of “God has given.”",
 bg:"The LORD sent word through Nathan to call Solomon Jedidiah (2 Samuel 12:25)."}),
ot1_absalom:OT1({name:"Absalom",forms:["Absalom"],resp:"AB-suh-lum",say:"ab suh lum",heb:"אַבְשָׁלוֹם",tr:"ʾAvshalom",strong:"H53",books:["2sam","1kgs"],
 plain:"David’s handsome third son, who killed his half-brother Amnon to avenge Tamar, then led a revolt against David and died caught by his hair in an oak (2 Samuel 3:3; 13:28–29; 15:10; 18:9–15). His name means “father of peace.”",
 bg:"David’s grief is one of the most painful passages in the Old Testament: “O my son Absalom, my son, my son Absalom! would God I had died for thee” (18:33)."}),
ot1_amnon:OT1({name:"Amnon",forms:["Amnon"],resp:"AM-non",say:"am non",heb:"אַמְנוֹן",tr:"ʾAmnon",strong:"H550",books:["2sam"],
 plain:"David’s oldest son, who assaulted his half-sister Tamar and was killed by Absalom two years later (2 Samuel 3:2; 13:1–14, 28–29). The name is probably related to “faithful,” but the meaning is uncertain.",
 bg:"David “was very wroth” but did nothing (13:21). Amnon is a different name from Ammon, the people descended from Lot."}),
ot1_tamar:OT1({name:"Tamar",forms:["Tamar"],resp:"TAY-mar",say:"tay mar",heb:"תָּמָר",tr:"Tamar",strong:"H8559",books:["2sam"],
 plain:"David’s daughter and Absalom’s full sister, who was assaulted by Amnon and then lived “desolate” in Absalom’s house (2 Samuel 13:1–20). The name means “date palm.”",
 bg:"Her plea was “do not force me; for no such thing ought to be done in Israel” (13:12). Absalom later named his own daughter Tamar (14:27)."}),
ot1_solomon:OT1({name:"Solomon / Jedidiah",forms:["Solomon","Jedidiah"],resp:"SOL-uh-mun",say:"sol uh mun",heb:"שְׁלֹמֹה",tr:"Shelomoh",strong:"H8010",books:["2sam","1kgs","2kgs","ezra","neh"],
 plain:"David’s son by Bathsheba and third king of Israel, who built the temple and was famous for wisdom (1 Kings 3:12; 6:1; 10:23–24). His name comes from shalom, “peace,” and the LORD also had Nathan call him Jedidiah, “beloved of the LORD” (2 Samuel 12:24–25).",
 bg:"His reign was peaceful (1 Kings 4:24–25), but his many foreign wives turned his heart away (11:1–6); the Book of Mormon calls David’s and Solomon’s many wives “abominable” (Jacob 2:24). Jesus said even Solomon “in all his glory was not arrayed like one of these” lilies (Matthew 6:29)."}),
ot1_bosheth:OT1({name:"Ish-bosheth / Jerubbesheth",forms:["Ish-bosheth","Jerubbesheth"],resp:"ish-BO-sheth",say:"ish bo sheth",heb:"אִישׁ־בֹּשֶׁת",tr:"ʾIsh-bosheth",strong:"H378",books:["2sam"],
 plain:"Ish-bosheth, Saul’s surviving son, was made king by Abner and reigned two years before two of his captains murdered him (2 Samuel 2:8–10; 4:5–7). His name means “man of shame,” but he was born Esh-baal, “man of Baal” (1 Chronicles 8:33), and later scribes replaced baal with bosheth, “shame.”",
 bg:"The same change turned Gideon’s name Jerubbaal into Jerubbesheth (2 Samuel 11:21) and Meribbaal into Mephibosheth (1 Chronicles 8:34)."}),
ot1_mephibosheth:OT1({name:"Mephibosheth",forms:["Mephibosheth"],resp:"meh-FIB-o-sheth",say:"meh fib o sheth",heb:"מְפִיבֹשֶׁת",tr:"Mefivosheth",strong:"H4648",books:["2sam"],
 plain:"Jonathan’s son, lame in both feet after his nurse dropped him as a child when news of Saul’s and Jonathan’s deaths came (2 Samuel 4:4). David restored Saul’s land to him and seated him at the king’s table “as one of the king’s sons” (9:6–11). His name was originally Merib-baal, “Baal contends” (1 Chronicles 8:34), with baal changed to bosheth, “shame.”",
 bg:"When David returned from fleeing Absalom, Mephibosheth said, “let him take all, forasmuch as my lord the king is come again in peace” (19:30)."}),
ot1_uzzah:OT1({name:"Uzzah / Perez-uzzah",forms:["Uzzah","Perez-uzzah"],resp:"UZ-uh",say:"uz uh",heb:"עֻזָּה",tr:"ʿUzzah",strong:"H5798",books:["2sam"],
 plain:"The man who reached out to steady the ark when the oxen stumbled as it rode on a cart toward Jerusalem, and died on the spot (2 Samuel 6:6–7). Uzzah means “strength,” and David named the place Perez-uzzah, “breach of Uzzah” (6:8).",
 bg:"The law said only Levites were to carry the ark (Numbers 4:15). A revelation to Joseph Smith alludes to him: the man “that putteth forth his hand to steady the ark of God, shall fall by the shaft of death” (D&C 85:8)."}),
ot1_obededom:OT1({name:"Obed-edom",forms:["Obed-edom"],resp:"O-bed-EE-dum",say:"o bed ee dum",heb:"עֹבֵד־אֱדֹם",tr:"ʿOved-ʾEdom",strong:"H5654",books:["2sam"],
 plain:"A Gittite in whose house the ark stayed three months after Uzzah’s death, and “the LORD blessed Obed-edom, and all his household” (2 Samuel 6:10–12). The name is usually read “servant of Edom.”",
 bg:"A man of this name is listed among the Levite gatekeepers and musicians in Chronicles (1 Chronicles 15:18, 21, 24)."}),
ot1_zion:OT1({name:"Zion",forms:["Zion"],resp:"ZY-un",say:"zye un",heb:"צִיּוֹן",tr:"Tsiyyon",strong:"H6726",books:["2sam","1kgs","2kgs"],
 plain:"The fortified hill David took from the Jebusites and called the city of David (2 Samuel 5:6–7). The name later grew to mean the temple hill, Jerusalem, and God’s people; its own meaning is uncertain.",
 bg:"“Zion” is where the LORD dwells (2 Kings 19:21, 31). Latter-day scripture says “this is Zion — THE PURE IN HEART” (D&C 97:21) and that the Lord’s people were called Zion “because they were of one heart and one mind” (Moses 7:18)."}),
ot1_jerusalem:OT1({name:"Jerusalem",forms:["Jerusalem"],resp:"jeh-ROO-suh-lem",say:"jeh roo suh lem",heb:"יְרוּשָׁלַיִם",tr:"Yerushalayim",strong:"H3389",books:["josh","judg","1sam","2sam","1kgs","2kgs","ezra","neh","esth"],
 plain:"The city David captured and made his capital, where Solomon built the temple (2 Samuel 5:5–9; 1 Kings 6:1). The name is often explained as “city of peace” (shalom) or “foundation of (the god) Shalem,” but the meaning is debated.",
 bg:"Before David it was held by the Jebusites and called Jebus (Judges 19:10; 1 Chronicles 11:4). “Salem,” where Melchizedek was king, may be the same place (Genesis 14:18; Psalm 76:2)."}),
ot1_ramah:OT1({name:"Ramah",forms:["Ramah"],resp:"RAY-muh",say:"ray muh",heb:"רָמָה",tr:"Ramah",strong:"H7414",books:["josh","judg","1sam","1kgs","2kgs","ezra","neh"],
 plain:"A common town name meaning “height,” used for several hill towns, so the verse has to show which one is meant. The best known is Samuel’s hometown, where he judged Israel and was buried (1 Samuel 1:19; 7:17; 25:1); another in Benjamin was fortified by King Baasha (1 Kings 15:17).",
 bg:"Jeremiah heard “a voice … in Ramah” of Rachel weeping for her children (Jeremiah 31:15), and Matthew applies it to Bethlehem (Matthew 2:18)."}),
ot1_mizpah:OT1({name:"Mizpah / Mizpeh",forms:["Ramath-mizpeh","Mizpeh","Mizpah"],resp:"MIZ-pah",say:"miz pah",heb:"מִצְפָּה",tr:"Mitspah",strong:"H4709",books:["josh","judg","1sam","1kgs","2kgs","neh"],
 plain:"The name of several places, from mitspah, “watchtower” or “lookout.” One in Benjamin was where Israel gathered against Benjamin and later repented under Samuel (Judges 20:1; 1 Samuel 7:5–6), and another was in Gilead, near Jephthah’s home (Judges 11:11, 29).",
 bg:"The first Mizpah, in Genesis 31:49, gave the saying “The LORD watch between me and thee, when we are absent one from another.”"}),
// ================= 1 and 2 Kings =================
ot1_rehoboam:OT1({name:"Rehoboam",forms:["Rehoboam"],resp:"ree-huh-BO-um",say:"ree huh bo um",heb:"רְחַבְעָם",tr:"Rechavʿam",strong:"H7346",books:["1kgs"],
 plain:"Solomon’s son, who answered the people’s request for lighter burdens with threats, so ten tribes broke away under Jeroboam (1 Kings 12:1–20). His name means “he enlarges the people,” a bitter irony for a king who lost most of them.",
 bg:"He ignored the elders’ advice and followed his young friends (12:6–14). The northern tribes cried, “What portion have we in David?” (12:16)."}),
ot1_jeroboam:OT1({name:"Jeroboam (son of Nebat)",forms:["Jeroboam"],resp:"jair-uh-BO-um",say:"jair uh bo um",heb:"יָרָבְעָם",tr:"Yarovʿam",strong:"H3379",books:["1kgs","2kgs"],
 plain:"An Ephraimite official of Solomon who became the first king of the northern kingdom (1 Kings 11:26; 12:20). His name is usually explained as “the people contend” or “may the people increase,” but this is uncertain.",
 bg:"He set up golden calves at Beth-el and Dan so that people would not go up to Jerusalem (1 Kings 12:26–30), and later writers measure every northern king by “the sins of Jeroboam the son of Nebat” (2 Kings 13:2)."}),
ot1_jeroboam2:OT1({name:"Jeroboam II (son of Joash)",forms:[],resp:"jair-uh-BO-um",say:"jair uh bo um",heb:"יָרָבְעָם",tr:"Yarovʿam",strong:"H3379",books:["2kgs"],
 plain:"The son of Jehoash, who ruled Israel forty-one years and restored its borders “from the entering of Hamath unto the sea of the plain,” as Jonah had foretold (2 Kings 14:23–28).",
 bg:"The prophets Amos and Hosea spoke in his reign (Amos 1:1; Hosea 1:1). He is a different king from the first Jeroboam."}),
ot1_bethel:OT1({name:"Beth-el",forms:["Beth-el"],resp:"BETH-el",say:"beth el",heb:"בֵּית־אֵל",tr:"Beit-ʾEl",strong:"H1008",books:["josh","judg","1sam","1kgs","2kgs"],
 plain:"A town in the hills north of Jerusalem whose name means “house of God.” Jacob gave it the name after his dream of the ladder, and it was earlier called Luz (Genesis 28:17–19).",
 bg:"After the kingdom split, Jeroboam made it a rival shrine with a golden calf (1 Kings 12:28–33), and Hosea mocks it as Beth-aven, “house of wickedness” (Hosea 4:15). Josiah destroyed its altar (2 Kings 23:15)."}),
ot1_elijah:OT1({name:"Elijah",forms:["Elijah"],resp:"ee-LY-juh",say:"ee lye juh",heb:"אֵלִיָּהוּ",tr:"ʾEliyyahu",strong:"H452",books:["1kgs","2kgs"],
 plain:"The prophet from Tishbe in Gilead who confronted King Ahab and the prophets of Baal and was taken up in a whirlwind with a chariot and horses of fire (1 Kings 17:1; 18:21–40; 2 Kings 2:11). His name means “my God is the LORD,” the very question at Mount Carmel.",
 bg:"Malachi promised that Elijah would return before the day of the LORD (Malachi 4:5–6). On 3 April 1836 in the Kirtland Temple, Elijah appeared and restored the sealing keys (D&C 110:13–16)."}),
ot1_ahab:OT1({name:"Ahab",forms:["Ahab"],resp:"AY-hab",say:"ay hab",heb:"אַחְאָב",tr:"ʾAchʾav",strong:"H256",books:["1kgs","2kgs"],
 plain:"King of Israel, son of Omri and husband of Jezebel, who built a temple of Baal in Samaria (1 Kings 16:29–33). The name means “brother of the father” (or “the father is a brother”), and its sense is uncertain.",
 bg:"He let Jezebel arrange the murder of Naboth for his vineyard (21:1–16). “There was none like unto Ahab, which did sell himself to work wickedness” (21:25)."}),
ot1_jezebel:OT1({name:"Jezebel",forms:["Jezebel"],resp:"JEZ-uh-bel",say:"jez uh bel",heb:"אִיזֶבֶל",tr:"ʾIzevel",strong:"H348",books:["1kgs","2kgs"],
 plain:"A Phoenician princess, daughter of Ethbaal king of the Sidonians, who married Ahab, promoted Baal worship, and killed the LORD’s prophets (1 Kings 16:31; 18:4, 13). The name is probably “where is the prince?” or “Baal is exalted,” but its meaning is debated.",
 bg:"Jehu had her thrown from a window, and dogs ate her body as Elijah had foretold (2 Kings 9:30–37; 1 Kings 21:23)."}),
ot1_jezreel:OT1({name:"Jezreel",forms:["Jezreel"],resp:"JEZ-ree-el",say:"jez ree el",heb:"יִזְרְעֶאל",tr:"Yizreʿʾel",strong:"H3157",books:["josh","judg","1sam","2sam","1kgs","2kgs"],
 plain:"A city and a broad fertile valley in the north of Israel, where Ahab had a palace and Naboth a vineyard (1 Kings 21:1) and where Jehu killed Jezebel (2 Kings 9:30–37). The name means “God sows.”",
 bg:"The valley was a main battleground road (Judges 6:33; 1 Samuel 29:1). Hosea turned the name from judgment to promise: “I will sow her unto me in the earth” (Hosea 2:23)."}),
ot1_jezreel_judah:OT1({name:"Jezreel (in Judah)",forms:[],resp:"JEZ-ree-el",say:"jez ree el",heb:"יִזְרְעֶאל",tr:"Yizreʿʾel",strong:"H3157",books:["josh","1sam"],
 plain:"A town in the hill country of Judah, not the northern valley and city. It was the home of David’s wife Ahinoam (1 Samuel 25:43; Joshua 15:56).",
 bg:""}),
ot1_elisha:OT1({name:"Elisha",forms:["Elisha"],resp:"ee-LY-shuh",say:"ee lye shuh",heb:"אֱלִישָׁע",tr:"ʾElishaʿ",strong:"H477",books:["1kgs","2kgs"],
 plain:"Elijah’s successor, whom Elijah called by throwing his cloak over him while he plowed with twelve yoke of oxen (1 Kings 19:16, 19). His name means “my God is salvation.”",
 bg:"He asked for “a double portion” of Elijah’s spirit (2 Kings 2:9). His name has the same root, yashaʿ, “to save,” as Joshua and Jesus."}),
ot1_naaman:OT1({name:"Naaman",forms:["Naaman"],resp:"NAY-uh-mun",say:"nay uh mun",heb:"נַעֲמָן",tr:"Naʿaman",strong:"H5283",books:["2kgs"],
 plain:"The commander of the Syrian army, a great man with leprosy, who was healed after washing seven times in the Jordan at Elisha’s word (2 Kings 5:1, 10–14). His name means “pleasant,” from the same root as Naomi.",
 bg:"His servants persuaded him: “if the prophet had bid thee do some great thing, wouldest thou not have done it? how much rather then, when he saith to thee, Wash, and be clean?” (5:13). Jesus mentions Naaman the Syrian in Luke 4:27."}),
ot1_gehazi:OT1({name:"Gehazi",forms:["Gehazi"],resp:"geh-HAY-zy",say:"geh hay zye",heb:"גֵּחֲזִי",tr:"Gechazi",strong:"H1522",books:["2kgs"],
 plain:"Elisha’s servant, who ran after Naaman for the silver and clothing Elisha had refused, lied about it, and was struck with Naaman’s leprosy (2 Kings 5:20–27). The meaning of the name is uncertain; “valley of vision” has been suggested.",
 bg:"He appears earlier as a faithful helper (4:12, 25–31) and later tells the king about Elisha’s miracles (8:4–5)."}),
ot1_jehu:OT1({name:"Jehu",forms:["Jehu"],resp:"JAY-hyoo",say:"jay hyoo",heb:"יֵהוּא",tr:"Yehuʾ",strong:"H3058",books:["1kgs","2kgs"],
 plain:"A commander of Israel’s army, anointed king by a young prophet sent by Elisha, who killed Joram, Ahaziah and Jezebel, wiped out Ahab’s house, and destroyed the worshippers of Baal (2 Kings 9–10). His name probably means “the LORD is he.”",
 bg:"The watchman said, “the driving is like the driving of Jehu the son of Nimshi; for he driveth furiously” (9:20). He ended Baal worship but kept Jeroboam’s golden calves (10:29–31)."}),
ot1_hezekiah:OT1({name:"Hezekiah",forms:["Hezekiah"],resp:"hez-eh-KY-uh",say:"hez eh kye uh",heb:"חִזְקִיָּהוּ",tr:"Chizqiyyahu",strong:"H2396",books:["2kgs"],
 plain:"A king of Judah who “trusted in the LORD God of Israel” (2 Kings 18:5), broke the bronze serpent, and prayed in the temple when Sennacherib’s army threatened Jerusalem (18:4; 19:14–19). His name means “the LORD strengthens” or “my strength is the LORD.”",
 bg:"An angel struck down 185,000 Assyrians in a night (19:35), and the LORD added fifteen years to Hezekiah’s life (20:6). He made “a pool, and a conduit” to bring water into the city (20:20), usually identified with the tunnel still visited in Jerusalem."}),
ot1_josiah:OT1({name:"Josiah",forms:["Josiah"],resp:"jo-SY-uh",say:"jo sye uh",heb:"יֹאשִׁיָּהוּ",tr:"Yoʾshiyyahu",strong:"H2977",books:["1kgs","2kgs"],
 plain:"A king of Judah who became king at eight, repaired the temple, and led a great reform after the book of the law was found there (2 Kings 22:1, 8–13; 23:1–25). The name is possibly “the LORD supports,” but the meaning is uncertain.",
 bg:"A prophet named him more than three hundred years earlier, “Josiah by name” (1 Kings 13:2), and Josiah did what was foretold at Beth-el (2 Kings 23:15–18). Lehi’s family left Jerusalem not long after, in the first year of Zedekiah (1 Nephi 1:4)."}),
ot1_manasseh_king:OT1({name:"Manasseh (king of Judah)",forms:["Manasseh"],resp:"muh-NASS-uh",say:"muh nass uh",heb:"מְנַשֶּׁה",tr:"Menashsheh",strong:"H4519",books:["2kgs"],
 plain:"A king of Judah, son of Hezekiah, who ruled fifty-five years, rebuilt the high places, raised altars to Baal, and “shed innocent blood very much” (2 Kings 21:1–6, 16). He is named for Joseph’s son (Genesis 41:51), and the name means “making to forget.”",
 bg:"The LORD said he would bring such evil upon Jerusalem that “whosoever heareth of it, both his ears shall tingle” (21:12). Second Chronicles 33:11–13 tells of his repentance, which Kings does not mention."}),
ot1_manasseh_nun:OT1({name:"Manasseh (or Moses?) in Judges 18:30",forms:[],resp:"muh-NASS-uh",say:"muh nass uh",heb:"מְנַשֶּׁה",tr:"Menashsheh",strong:"H4519",books:["judg"],
 plain:"Judges 18:30 reads “Jonathan, the son of Gershom, the son of Manasseh,” but in the Hebrew text the letter nun in “Manasseh” is raised above the line. Jewish scribes seem to have added it to turn “Moses” (Mosheh) into “Manasseh” so that Moses’ grandson would not be named as priest of an idol shrine, and many scholars read the verse as “son of Moses.”",
 bg:"Gershom was Moses’ firstborn son (Exodus 2:22)."}),
ot1_jachinboaz:OT1({name:"Jachin and Boaz",forms:["Jachin","Boaz"],resp:"JAY-kin, BO-az",say:"jay kin, bo az",heb:"יָכִין וּבֹעַז",tr:"Yakhin, Boʿaz",strong:"H3199 / H1162",books:["1kgs"],
 plain:"The two bronze pillars that Hiram of Tyre cast for the porch of Solomon’s temple: the right one named Jachin and the left Boaz (1 Kings 7:15–21). Jachin probably means “he establishes”; Boaz is often explained as “in him is strength,” but both are uncertain.",
 bg:"Together they may read as a short prayer for the king’s house, but scholars debate it. Boaz is also the name of David’s ancestor in Ruth."}),
// ================= Ezra, Nehemiah, Esther =================
ot1_zerubbabel:OT1({name:"Zerubbabel",forms:["Zerubbabel"],resp:"zuh-RUB-uh-bul",say:"zuh rub uh bul",heb:"זְרֻבָּבֶל",tr:"Zerubbavel",strong:"H2216",books:["ezra","neh"],
 plain:"A descendant of David who led the first group of exiles home from Babylon and, as governor with Jeshua the priest, rebuilt the altar and then the temple (Ezra 3:2, 8; 5:2). The name probably means “seed of Babylon,” that is, born there.",
 bg:"He is in Jesus’ ancestry (Matthew 1:12–13), and Haggai calls him the LORD’s “signet” (Haggai 2:23)."}),
ot1_ezra:OT1({name:"Ezra",forms:["Ezra"],resp:"EZ-ruh",say:"ez ruh",heb:"עֶזְרָא",tr:"ʿEzra",strong:"H5830",books:["ezra","neh"],
 plain:"A priest and scribe, “a ready scribe in the law of Moses” (Ezra 7:6), who came from Babylon under Artaxerxes, taught the law, and led the people to end marriages to foreign wives (7:10; 10:1–12). He later read the law aloud at the Water Gate (Nehemiah 8:1–8). The name is a short form meaning “help.”",
 bg:"He traced his line to Aaron (Ezra 7:1–5). Ezra and Nehemiah were counted as one book in the Hebrew Bible."}),
ot1_nehemiah:OT1({name:"Nehemiah",forms:["Nehemiah"],resp:"nee-uh-MY-uh",say:"nee uh my uh",heb:"נְחֶמְיָה",tr:"Nechemyah",strong:"H5166",books:["neh"],
 plain:"The cupbearer of King Artaxerxes who asked leave to go to Jerusalem and, as governor, led the rebuilding of the wall in fifty-two days (Nehemiah 1:11; 2:1–8; 6:15). His name means “the LORD comforts.”",
 bg:"He prayed before he acted (1:4–11; 2:4) and faced opposition from Sanballat and Tobiah (2:10, 19)."}),
ot1_sanballat:OT1({name:"Sanballat",forms:["Sanballat"],resp:"san-BAL-at",say:"san bal at",heb:"סַנְבַלַּט",tr:"Sanvallat",strong:"H5571",books:["neh"],
 plain:"The Horonite, a leader in Samaria who opposed Nehemiah with mockery and plots (Nehemiah 2:10, 19; 4:1–8; 6:1–14). His name is Babylonian, Sin-uballit, “Sin (the moon god) has given life.”",
 bg:"Letters from Elephantine in Egypt (about 407 BC) name “Sanballat, governor of Samaria” and his sons Delaiah and Shelemiah, whose names end in “Yah.”"}),
ot1_artaxerxes:OT1({name:"Artaxerxes",forms:["Artaxerxes"],resp:"ar-tuh-ZURK-seez",say:"ar tuh zurk seez",heb:"אַרְתַּחְשַׁסְתָּא",tr:"ʾArtachshasta",strong:"H783",books:["ezra","neh"],
 plain:"A Persian king who first stopped the rebuilding of Jerusalem (Ezra 4:7–23) and later sent Ezra and then Nehemiah there with royal support (Ezra 7; Nehemiah 2). His Persian name is usually explained as “whose kingdom is justice.”",
 bg:"Artaxerxes I (reigned 465–424 BC) is the usual identification. Nehemiah was his cupbearer (Nehemiah 2:1)."}),
ot1_nethinim:OT1({name:"Nethinims",forms:["Nethinims"],resp:"NETH-ih-nims",say:"neth ih nims",heb:"נְתִינִים",tr:"netinim",strong:"H5411",books:["ezra","neh"],
 plain:"Temple servants who helped the Levites; the Hebrew netinim means “given ones,” from natan, “to give” (Ezra 2:43–58; 8:20).",
 bg:"They were people “whom David and the princes had appointed for the service of the Levites” (Ezra 8:20), and Artaxerxes’ decree freed them from tax (7:24)."}),
ot1_esther:OT1({name:"Esther / Hadassah",forms:["Esther","Hadassah"],resp:"ES-ter",say:"es ter",heb:"אֶסְתֵּר",tr:"ʾEster",strong:"H635",books:["esth"],
 plain:"A Jewish orphan raised by her cousin Mordecai, who became queen of Persia and risked her life to ask King Ahasuerus to save her people from Haman (Esther 2:7, 17; 4:16; 7:3–4). Her Hebrew name was Hadassah, “myrtle” (2:7); Esther is probably Persian for “star,” though some link it to Ishtar.",
 bg:"The book never names God, and some readers hear in “Esther” the Hebrew “I will hide,” echoing “I will surely hide my face” (Deuteronomy 31:18). Mordecai asked her, “who knoweth whether thou art come to the kingdom for such a time as this?” (Esther 4:14)."}),
ot1_mordecai:OT1({name:"Mordecai",forms:["Mordecai"],resp:"MOR-deh-ky",say:"mor deh kye",heb:"מָרְדְּכַי",tr:"Mordekhai",strong:"H4782",books:["esth"],
 plain:"A Jew in Shushan, Esther’s cousin and guardian, who refused to bow to Haman, uncovered a plot against the king, and rose to be next to Ahasuerus (Esther 2:5–7, 22; 3:2; 10:3). His name probably comes from Marduk, the chief god of Babylon.",
 bg:"Like Daniel, who was renamed Belteshazzar (Daniel 1:7), he bore a name from the culture of the exile. He is “great among the Jews” (10:3)."}),
ot1_haman:OT1({name:"Haman",forms:["Haman"],resp:"HAY-mun",say:"hay mun",heb:"הָמָן",tr:"Haman",strong:"H2001",books:["esth"],
 plain:"The Agagite who became the king’s chief minister and planned to destroy all the Jews because Mordecai would not bow; he cast lots (pur) for the day and was hanged on his own gallows (Esther 3:1–7; 7:9–10). The meaning of the name is uncertain; it may be Persian or Elamite.",
 bg:"The story turns on reversals: Haman had to lead Mordecai through the city in honor (6:6–11), and the gallows built for Mordecai were used for him (7:10)."}),
ot1_ahasuerus:OT1({name:"Ahasuerus",forms:["Ahasuerus"],resp:"uh-haz-yoo-EE-rus",say:"uh haz yoo ee rus",heb:"אֲחַשְׁוֵרוֹשׁ",tr:"ʾAchashverosh",strong:"H325",books:["ezra","esth"],
 plain:"The Persian king who ruled “from India even unto Ethiopia, over an hundred and seven and twenty provinces” (Esther 1:1) and chose Esther as queen (2:17). He is usually identified with Xerxes I (reigned 486–465 BC); his Persian name Khshayarsha is sometimes explained as “ruler of heroes,” but this is uncertain.",
 bg:"Ezra 4:6 mentions him as the king to whom enemies of Judah wrote an accusation. Greek historians tell of his defeat at Salamis in 480 BC."}),
ot1_vashti:OT1({name:"Vashti",forms:["Vashti"],resp:"VASH-tye",say:"vash tye",heb:"וַשְׁתִּי",tr:"Vashti",strong:"H2060",books:["esth"],
 plain:"The queen who refused King Ahasuerus’ command to appear at his feast and was removed from being queen (Esther 1:9–19). The name is probably Persian, perhaps “the best” or “beautiful,” but this is uncertain.",
 bg:"Her removal opens the way for Esther (2:1–4, 17). The text says only that she “refused to come at the king’s commandment” (1:12)."}),
ot1_purim:OT1({name:"Purim / Pur",forms:["Purim","Pur"],resp:"POO-rim",say:"poo rim",heb:"פּוּרִים",tr:"Purim",strong:"H6332",books:["esth"],
 plain:"The Jewish festival that remembers how Esther and Mordecai saved the Jews from Haman (Esther 9:20–28). The text explains the name: “they called these days Purim after the name of Pur,” the “lot” Haman cast to choose the day (9:26; 3:7).",
 bg:"The word pur is thought to come from Akkadian puru, “lot.” The days are kept with the reading of the book, “sending portions one to another, and gifts to the poor” (9:22)."}),
// ================= Peoples, gods and words =================
ot1_philistines:OT1({name:"Philistines",forms:["Philistines","Philistine"],resp:"FIL-ih-steens",say:"fil ih steens",heb:"פְּלִשְׁתִּים",tr:"Pelishtim",strong:"H6430",books:["josh","judg","1sam","2sam","1kgs","2kgs"],
 plain:"A people from the Aegean world who settled the coastal plain, with five main cities (Gaza, Ashkelon, Ashdod, Ekron and Gath), and were Israel’s chief enemy from Samson to David (Joshua 13:2–3; 1 Samuel 4–7; 17). The Hebrew name is probably from Peleset, the “sea peoples” of Egyptian records, and its meaning is uncertain.",
 bg:"The Greeks and Romans later called the land Palestine from the same name. Israel called their champion “this uncircumcised Philistine” (1 Samuel 17:26), and they kept a monopoly on ironworking (13:19–22)."}),
ot1_edomites:OT1({name:"Edomites",forms:["Edomites","Edomite"],resp:"EE-dum-ites",say:"ee dum ites",heb:"אֱדוֹמִי",tr:"ʾEdomi",strong:"H130",books:["1sam","1kgs","2kgs"],
 plain:"The people of Edom, descended from Esau and living south and east of the Dead Sea. Doeg the Edomite, Saul’s chief herdsman, killed eighty-five priests at Nob (1 Samuel 21:7; 22:18).",
 bg:"David conquered Edom (1 Kings 11:15–17), and Edom later revolted from Judah (2 Kings 8:20–22)."}),
ot1_baal:OT1({name:"Baal",forms:["Baal","Baalim"],resp:"BAH-al",say:"bah al",heb:"בַּעַל",tr:"Baʿal",strong:"H1168",books:["judg","1sam","1kgs","2kgs"],
 plain:"The Canaanite storm and fertility god, worshipped by many Israelites and promoted by Ahab and Jezebel (1 Kings 16:31–32). Baal means “lord,” “master” or “owner,” and also “husband”; Baalim is the plural, the many local Baals.",
 bg:"Elijah asked on Mount Carmel, “How long halt ye between two opinions? if the LORD be God, follow him: but if Baal, then follow him” (1 Kings 18:21). Gideon’s second name, Jerubbaal, means “let Baal plead” (Judges 6:32)."}),
ot1_baalzebub:OT1({name:"Baal-zebub",forms:["Baal-zebub"],resp:"BAH-al ZEE-bub",say:"bah al zee bub",heb:"בַּעַל זְבוּב",tr:"Baʿal Zevuv",strong:"",books:["2kgs"],
 plain:"The god of Ekron, whom King Ahaziah of Israel sent messengers to ask whether he would recover from his fall; Elijah stopped them (2 Kings 1:2–6). The name means “lord of the flies,” probably a mocking change of Baal-zebul, “Baal the prince.”",
 bg:"In the New Testament the name appears as Beelzebub, “the prince of the devils” (Matthew 12:24)."}),
ot1_baalplaces:OT1({name:"Baal- place names",forms:["Baal-gad","Baal-hermon","Baal-tamar","Baal-perazim","Baal-hazor","Baal-shalisha","Kirjath-baal","Bamoth-baal","Beth-baal-meon"],resp:"BAH-al",say:"bah al",heb:"בַּעַל",tr:"Baʿal",strong:"H1168",books:["josh","judg","2sam","2kgs"],
 plain:"Places named with baal, “lord” or “owner,” such as Baal-gad, Baal-hermon and Baal-hazor, probably after a local shrine or the “lord” of that spot. They are not all connected with the god Baal.",
 bg:"At Baal-perazim, “lord of breakings-through,” David said, “The LORD hath broken forth upon mine enemies before me, as the breach of waters” (2 Samuel 5:20), turning the name to the LORD’s credit."}),
ot1_asherah:OT1({name:"Asherah (“grove”)",forms:["grove","groves"],resp:"uh-SHEER-uh",say:"uh sheer uh",heb:"אֲשֵׁרָה",tr:"ʾAsherah",strong:"H842",books:["judg","1kgs","2kgs"],
 plain:"In the KJV, “grove” and “groves” translate asherah, a wooden pole or tree standing for the goddess Asherah, set beside an altar (Judges 6:25–26). Gideon was told to cut one down, King Manasseh put one in the temple (2 Kings 21:7), and Josiah burned it (23:6).",
 bg:"Some inscriptions from about 800 BC mention “the LORD … and his asherah,” which suggests how widespread the symbol was, even among those who worshipped the LORD."}),
ot1_ashtoreth:OT1({name:"Ashtoreth",forms:["Ashtoreth","Ashtaroth"],resp:"ASH-toh-reth",say:"ash toh reth",heb:"עַשְׁתֹּרֶת",tr:"ʿAshtoret",strong:"H6253",books:["judg","1sam","1kgs","2kgs"],
 plain:"The Canaanite goddess of love and war (Astarte); Ashtaroth is the plural, used for goddesses in general (Judges 2:13; 10:6). Solomon followed “Ashtoreth the goddess of the Zidonians” (1 Kings 11:5), and Saul’s armor was put in her temple (1 Samuel 31:10).",
 bg:"Many scholars think the Hebrew spelling uses the vowels of bosheth, “shame,” as a deliberate insult."}),
ot1_molech:OT1({name:"Molech / Milcom",forms:["Molech","Milcom"],resp:"MO-lek",say:"mo leck",heb:"מֹלֶךְ",tr:"Molekh",strong:"H4432",books:["1kgs","2kgs"],
 plain:"Names for the god of the Ammonites, for whom Solomon built a high place (1 Kings 11:5, 7) and to whom children were given “to pass through the fire” (2 Kings 23:10, 13). The names come from melek, “king.”",
 bg:"Many scholars think “Molech” was written with the vowels of bosheth, “shame,” to mock the god. Leviticus 18:21 forbids giving children to Molech."}),
ot1_dagon:OT1({name:"Dagon",forms:["Dagon"],resp:"DAY-gon",say:"day gon",heb:"דָּגוֹן",tr:"Dagon",strong:"H1712",books:["judg","1sam"],
 plain:"The chief god of the Philistines, with temples at Gaza and Ashdod (Judges 16:21–23; 1 Samuel 5:1–5). The name is usually linked to dagan, “grain,” though older writers connected it with dag, “fish.”",
 bg:"When the ark was placed in his temple, his statue fell on its face and was broken, so that “only the stump of Dagon was left to him” (1 Samuel 5:3–4)."}),
ot1_ephod:OT1({name:"ephod",forms:["ephod"],resp:"EE-fod",say:"ee fod",heb:"אֵפוֹד",tr:"ʾefod",strong:"H646",books:["judg","1sam","2sam"],
 plain:"A sacred garment. The high priest’s ephod was richly worked in gold, blue, purple and scarlet (Exodus 28:6–8), while priests and the boy Samuel wore a plain linen ephod (1 Samuel 2:18; 22:18). It was used to ask the LORD’s will (23:6–12; 30:7–8).",
 bg:"Gideon made one of gold from Midian’s spoil, and “all Israel went thither a whoring after it” (Judges 8:27). Micah’s house shrine also had one (17:5)."}),
ot1_lordofhosts:OT1({name:"LORD of hosts",forms:["LORD of hosts"],resp:"tseh-vah-OTE",say:"tseh vah ote",heb:"יְהוָה צְבָאוֹת",tr:"YHWH tsevaʾot",strong:"H6635",books:["1sam","2sam","1kgs","2kgs"],
 plain:"A title of God, “the LORD of armies,” meaning the LORD who commands Israel’s armies and the armies of heaven. It first appears in the Bible in 1 Samuel 1:3, and David used it against Goliath: “I come to thee in the name of the LORD of hosts” (17:45).",
 bg:"The New Testament has it as “Lord of Sabaoth” (Romans 9:29; James 5:4), and a revelation explains Sabaoth as “the creator of the first day, the beginning and the end” (D&C 95:7)."}),
ot1_namesake:OT1({name:"Not the better-known one of this name",forms:[],resp:"",say:"",heb:"",tr:"",strong:"",books:["josh","2sam","1kgs","neh"],
 plain:"In this verse the name belongs to a different person or place from the better-known one with the same or a similar name. Many Hebrew names were common, so the verse’s own details show who or what is meant.",
 bg:""})
});
